{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE prolicious-wh.maplemonk.prolicious_wh_FACEBOOK_CONSOLIDATED AS select Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,\'FACEBOOK\' as Account_Name ,Account_ID ,Campaign_Name ,Campaign_ID ,ads.status ,ads.effective_status ,cre.thumbnail_url ,cast(Fb.date_start as date) Date ,SUM(CLICKS) Clicks ,sum(ifnull(inline_link_clicks,0)) Link_Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(REACH) REACH ,SUM(ifnull(Fc.Conversions,0)) Conversions ,SUM(case when fb.ad_id = \'120231072661300057\' and cast(Fb.date_start as date) = \'2025-08-27\' then 0 else ifnull(Fcv.Conversion_Value,0) end) Conversion_Value ,sum(ifnull(fd.add_to_carts,0)) Add_to_carts ,sum(ifnull(fdv.add_to_cart_value,0)) Add_to_cart_value ,sum(ifnull(fe.landing_page_views,0)) Landing_page_views ,sum(ifnull(ff.initiate_checkouts,0)) Initiate_checkouts ,sum(ifnull(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'FACEBOOK\' Channel ,\'FACEBOOK\' Account from prolicious-wh.maplemonk.Prolicious_FbAds_New_customcampaigns_data FB left join ( select ad_id ,ad_name ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Conversions from prolicious-wh.maplemonk.Prolicious_FbAds_New_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start left join ( select ad_id ,ad_name ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Conversion_Value from prolicious-wh.maplemonk.Prolicious_FbAds_New_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start left join ( SELECT CAST(id AS STRING) AS ad_id, status, effective_status FROM prolicious-wh.maplemonk.facebook_prolicious_ads qualify row_number() over (partition by CAST(id AS STRING) order by updated_time desc) = 1 ) ads ON CAST(FB.ad_id AS STRING) = ads.ad_id left join ( select id, JSON_VALUE(creative, \'$.thumbnail_url\') AS thumbnail_url from maplemonk.facebook_prolicious_ads_with_creatives_stream qualify row_number() over (partition by id order by 1) = 1 ) cre on cre.id = fb.ad_id left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) add_to_carts from prolicious-wh.maplemonk.Prolicious_FbAds_New_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Add_to_cart_Value from prolicious-wh.maplemonk.Prolicious_FbAds_New_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from prolicious-wh.maplemonk.Prolicious_FbAds_New_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Initiate_checkouts from prolicious-wh.maplemonk.Prolicious_FbAds_New_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Initiate_checkouts_Value from prolicious-wh.maplemonk.Prolicious_FbAds_New_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start where not(upper(Campaign_Name) in (\'TOF_FBIG_POST BOOST_THIS\',\'TOF_FBIG_LEAD_FEB\')) group by Adset_Name, Adset_ID,fb.ad_id,fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID,Fb.date_start,ads.status,ads.effective_status,cre.thumbnail_url ;",
                    "transaction": true
